public class InnerGatewayMCPGatewayConfigurationFactory(Action<Humidifier.BedrockAgentCore.GatewayTypes.MCPGatewayConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.GatewayTypes.MCPGatewayConfiguration>
{

    internal InnerGatewayStreamingConfigurationFactory StreamingConfigurationFactory { get; set; }

    internal InnerGatewaySessionConfigurationFactory SessionConfigurationFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.GatewayTypes.MCPGatewayConfiguration Create()
    {
        var mCPGatewayConfigurationResult = CreateMCPGatewayConfiguration();
        factoryAction?.Invoke(mCPGatewayConfigurationResult);

        return mCPGatewayConfigurationResult;
    }

    private Humidifier.BedrockAgentCore.GatewayTypes.MCPGatewayConfiguration CreateMCPGatewayConfiguration()
    {
        var mCPGatewayConfigurationResult = new Humidifier.BedrockAgentCore.GatewayTypes.MCPGatewayConfiguration();

        return mCPGatewayConfigurationResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.GatewayTypes.MCPGatewayConfiguration result)
    {
        base.CreateChildren(result);

        result.StreamingConfiguration ??= StreamingConfigurationFactory?.Build();
        result.SessionConfiguration ??= SessionConfigurationFactory?.Build();
    }

} // End Of Class

